@router.post("/auth/passwordless/verify-otp")
async def verify_passwordless_otp(
    payload: OTPVerificationPayload,
    redis: Redis = Depends(get_redis_client),
    db: AsyncSession = Depends(get_db)
):
    cache_key = f"auth_otp:{payload.destination_email}"
    stored_code = await redis.get(cache_key)
    if not stored_code or stored_code != payload.otp_code:
        raise HTTPException(status_code=400, detail="Invalid or expired OTP code")

    await redis.delete(cache_key)
    user = await db.scalar(select(User).where(User.email == payload.destination_email))
    if not user:
        raise HTTPException(status_code=404, detail="User account not found")

    auth_token = issue_session_jwt(user.id, user.role)
    return {"access_token": auth_token, "role": user.role}
